import{_ as t,o,c as n,j as a,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/16-我们携手走来，却不尽了解彼此.md","filePath":"books/attached/16-我们携手走来，却不尽了解彼此.md","lastUpdated":1794298621000}'),r={name:"books/attached/16-我们携手走来，却不尽了解彼此.md"};function l(_,e,d,c,i,p){return o(),n("div",null,[...e[0]||(e[0]=[a("h3",{id:"我们携手走来-却不尽了解彼此",tabindex:"-1"},[s("我们携手走来，却不尽了解彼此 "),a("a",{class:"header-anchor",href:"#我们携手走来-却不尽了解彼此","aria-label":'Permalink to "我们携手走来，却不尽了解彼此"'},"​")],-1),a("p",null,"卡伦为自己太过依赖对方而感到羞愧，而蒂姆对自己在依恋关系中的角色又太不尽责，这并不奇怪，也并不是他们的过错。归根结底，我们所处的文化对那些亲密关系的需求颇有微词，一味吹捧独立性，反而磨灭了人们的依赖感。而我们被这种观念潜移默化，并不见得是一件好事。",-1),a("p",null,"有一种由来已久的错误观念，就是认为人们都应该在情感上自我满足。在不久以前，整个西方社会还普遍认为，孩子应该学会独立，才能更加快乐地成长。随后，起码在儿童研究领域，依恋理论的出现颠覆了这种观念。在20世纪40年代，专家们还认为家长的“溺爱”会让那些依恋性强、没安全感的孩子长大以后产生情感上的缺陷和失调。他们告诫家长，不要对自己的小孩付诸太多关注，而应该放任他们哭上几个小时，严格按照时间计划来喂他们吃饭。而医院里住院的孩子，也要与父母隔开，只能透过玻璃隔板来看望他们。社会工作者们一旦发现父母有丝毫的溺爱迹象，就会将孩子带离原本的家，将他们安置到寄养服务机构里去。",-1),a("p",null,"人们一贯认为，父母与孩子之间应该保持适当的距离，而肢体爱抚的表达也应该适当收敛。在20世纪20年代的畅销育儿读物，《婴幼儿心理卫生》（Psychological Care of Infant and Child）一书中，作者约翰·布劳德斯·沃特森（John Broadus Watson）极力抨击了“母亲对孩子的宠溺”，并将此书献给“养育出了快乐孩子的一流母亲”。未被溺爱的孩子们将成长为果敢、无畏、独立、适应力强并且善于解决问题的人，他们除非是生理上的不适，否则不会哭闹；他们对于学习和玩乐都能十分专注，也不会对任何地点或任何人产生过度的依赖。",-1),a("p",null,"20世纪50至60年代，玛丽·安斯沃思与约翰·鲍尔比开创性地提出了依恋理论，而在此之前，心理学家们一直没有对亲子关系产生重视。那时候普遍的观点是，孩子对于母亲的依恋，完全是因为母亲的供给和养育而衍生出来的，孩子们将母亲和自己所需的养分联系起来，因此才产生了依恋。但是鲍尔比发现，即使孩子得到了成长所需的足够食物，但是缺乏依恋对象，也依然不能够正常地发展（比如那些在二战期间无家可归的孩子，或是从小在孤儿院长大的孩子）。这些缺乏依恋对象的孩子，在心智、情感与社会发展上都会相对迟缓。安斯沃思和鲍尔比的研究，共同解释了这样的事实：对孩子的生存来说，儿童与养育者之间的联系，同水和食物一样不可或缺。",-1)])])}const m=t(r,[["render",l]]);export{f as __pageData,m as default};
